/** Width/height of each flag's own artwork, read from its viewBox at generation
 *  time.
 *
 *  The renderer sizes the image box to COVER the hexagon, and it can only do
 *  that if it knows the art's real shape. Assuming 1:1 for a 4:3 flag letterboxes
 *  it: thin white bands above and below, inside the hexagon. That is the exact
 *  bug the flag-hex notes warn about, and it reappeared here the moment a second
 *  art source (flag-icons 4x3, alongside nimiq.tech's 1x1) entered the set.
 *
 *  Derived rather than hand-listed, so adding a flag of any shape can never
 *  reintroduce it. FLAG_FIT still owns pan and zoom, which are judgement calls;
 *  this is measurement. */
export const FLAG_ASPECT: Record<string, number> = {
  "ae": 1.3333,
  "ar": 1.3333,
  "cl": 1.3333,
  "cr": 1.3333,
  "gm": 1.3333,
  "gt": 1.3333,
  "hk": 1.3333,
  "nz": 1.3333,
  "sg": 1.3333,
  "tw": 1.3333,
  "us": 1.3333,
};

/** A data: URI for a flag's SVG, suitable for an <image href>. */
export function flagDataUrl(code: string): string {
  const svg = FLAG_SVG[code.toLowerCase()];
  return svg ? "data:image/svg+xml," + encodeURIComponent(svg) : "";
}
